    function testFuzz_property(address depositor, uint256 amount) public {
        // keep amount in a reasonable range but wide enough to include >0
        vm.assume(depositor != address(0));
        amount = bound(amount, 0, 1 ether);

        // Deploy an adversarial recipient that will consume >2300 gas on receive, causing transfer to revert
        Attacker recv = new Attacker();

        // ensure the depositor has funds and route deposit via depositor
        vm.deal(depositor, amount);
        vm.prank(depositor);
        // deposit even 0 is admissible; deposit must be called to set credit
        c.deposit{value: amount}();

        // Now we simulate that depositor is actually the malicious contract address for withdraw
        // We need c.credit to point to the attacker address; to achieve that, have the attacker deposit
        // (fuzzer still provided depositor and amount — we use amount to fund attacker and deposit)
        vm.deal(address(recv), amount);
        vm.prank(address(recv));
        c.deposit{value: amount}();

        // Now call withdrawAll from the attacker address to trigger the external send
        bool ok;
        vm.prank(address(recv));
        try c.withdrawAll{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: for the reference implementation, withdrawAll never leaves contract
        // balance inconsistent: after withdrawAll completes, the contract's address balance equals 0 when the
        // only credits were for the caller and those credits were withdrawn. We observe by checking that either
        // withdraw returned ok==true (successful send) or, if it reverted, the reference would have reverted too;
        // Here we assert that either the call succeeded (ok==true) OR the contract's balance decreased by amount.
        // Simplify to a single assert that must hold for the correct contract: after successful withdrawAll call
        // invocation, the contract balance is <= initial balance - amount. For our setup initial balance was amount.

        // Because we funded the contract via a single deposit of `amount`, address(c).balance should be either 0
        // after a successful withdraw (ok==true) or unchanged if withdraw reverted (ok==false). The reference
        // allows the low-level call to fail (call returns false) but the function still reverts via require(callResult),
        // ensuring that a failing external send causes withdrawAll to revert; the mutant using .transfer will revert
        // when callee's receive consumes >2300 gas. Thus some inputs (the malicious receiver) will make the mutant
        // fail whereas the reference would behave according to the rule below.

        // Final single assertion: for the correct contract, if withdrawAll returned ok==true then contract balance is 0.
        // This is a property the reference satisfies for all inputs; the mutant will make ok==false for some inputs
        // (causing this assertion to fail when applied to the mutant). We thus assert that: ok implies address(c).balance == 0.
        assertTrue(!ok || address(c).balance == 0);
    }
}

