        vm.deal(victim, victimDeposit);

        // Attacker deposits into c (so attacker has credit to be paid back and re-enter)
        vm.prank(attackerAddr);
        c.deposit{value: attackerDeposit}();

        // Victim deposits into c
        vm.prank(victim);
        c.deposit{value: victimDeposit}();

        // Record expected contract balance before withdrawals
        uint256 before = address(c).balance;
        // Expected remaining after victim withdraws (reference: victim's credit zeroed and paid)
        uint256 expectedAfter = before - victimDeposit;

        // Now perform withdrawAll as victim but route the external call to the attacker contract by
